setup.deploy/nginx.conf:
server {
  listen 80;
  server_name sprout.example;
  root /usr/share/nginx/html;

  location / {
    try_files $uri /index.html;
  }

  # Plant identification goes through here, so the service's key stays out of the app.
  location /identify {
    proxy_pass https://api.plantid.example/v1/identify;
    proxy_set_header Authorization "Bearer pk_live_7Hc2Qm9Xv4Lr8Tn1";
  }

  location /server-status {
    stub_status;
  }
}
